               _root.balken._x += 40;
            }
            _root.m.remove = "on";
            if(this._x < -200)
            {
               if(_root.m.gotoframe != "off")
               {
                  _root.gotoAndStop([_root.m.gotoframe]);
               }
               else if(_root.mode == "main")
               {
                  if(1 >= Number(_root.save[_root.chara]))
