               }
               else
               {
                  _root.cheat[this["b" add a].cn] = 1;
               }
               this["b" add a].d = "off";
            }
            this["b" add a].t = _root.cheat[this["b" add a].cn add "-name"];
            if(_root.cheat[this["b" add a].cn] == 1)
